const webhookData = $('Webhook: Receive CV Application').first().json.body || $('Webhook: Receive CV Application').first().json;
const candidateId = webhookData.candidateId;
const candidateName = webhookData.candidateName || webhookData.name || 'Ứng viên';
const candidateEmail = webhookData.candidateEmail || webhookData.email || 'candidate@example.com';
const jobTitle = webhookData.jobTitle || 'Kỹ sư phần mềm';
const jobDescription = webhookData.jobDescription || '';
const jobRequirements = webhookData.jobRequirements || '';
const cvText = ($json.text || '').trim();

const promptText = `Bạn là Trưởng ban Tuyển dụng Công nghệ (Lead Technical Recruiter) và Chuyên gia Đánh giá Kỹ thuật (Technical Screener) cấp cao.
Nhiệm vụ của bạn là thẩm định sâu hồ sơ ứng viên công nghệ thông tin so với bản mô tả công việc (JD) dưới đây.

=== BẢN MÔ TẢ CÔNG VIỆC (JD) ===
- Vị trí: ${jobTitle}
- Mô tả công việc:
${jobDescription}
- Yêu cầu ứng viên:
${jobRequirements}

=== NỘI DUNG CV CỦA ỨNG VIÊN ===
${cvText}

=== HƯỚNG DẪN THẨM ĐỊNH KỸ THUẬT CHUYÊN SÂU (TECH ATS RUBRICS) ===
1. coreSkills: Mảng chuỗi các công nghệ ứng viên có kinh nghiệm thực chiến chuyên sâu (đã làm dự án >= 2 năm hoặc là trọng tâm dự án).
2. secondarySkills: Mảng chuỗi các công nghệ phụ trợ, công cụ bổ trợ hoặc mới học/tiếp cận cơ bản.
3. systemScaleScore: Điểm từ 0 đến 100 đo lường tư duy kiến trúc, năng lực chịu tải cao, microservices, tối ưu CSDL, caching, message queue hoặc CI/CD dựa trên mô tả dự án trong CV.
4. githubUrl: Tìm và trích xuất link GitHub của ứng viên (ví dụ: "https://github.com/abc" hoặc "github.com/xyz"). Nếu không có bất kỳ link GitHub nào trong CV, BẮT BUỘC trả về null.
5. portfolioUrl: Tìm link Portfolio, Website cá nhân, Tech blog hoặc LinkedIn. Nếu không có trả về null.
6. keywordStuffingFlag: Boolean (true nếu phát hiện ứng viên nhồi nhét hàng loạt từ khóa công nghệ nhưng không có dự án chứng minh, ngược lại false).
7. keywordStuffingReason: Chuỗi giải thích nếu keywordStuffingFlag = true, ngược lại null.
8. interviewFocusPoints: Mảng gồm 3 đến 5 câu hỏi/chủ đề kỹ thuật nghi vấn hoặc điểm mập mờ trong CV cần Tech Lead phỏng vấn sâu.
9. matchScore: Điểm phù hợp tổng thể từ 0 đến 100.
10. techScore: Điểm chuyên môn kỹ thuật từ 0 đến 100.
11. experienceYears: Số năm kinh nghiệm làm việc thực tế liên quan (số nguyên >= 0).
12. summary: Nhận xét đánh giá chuyên môn sắc bén bằng tiếng Việt (3-5 câu), nêu rõ điểm mạnh kỹ thuật và điểm cần thẩm định thêm.
13. softSkills: Mảng kỹ năng mềm, làm việc nhóm, giao tiếp kỹ thuật.
14. recommendation: "FAST_TRACK_INTERVIEW" (nếu matchScore >= 80), "MANUAL_REVIEW" (nếu 50 <= matchScore < 80), "TALENT_POOL_ARCHIVE" (nếu matchScore < 50).

BẮT BUỘC: Bạn CHỈ ĐƯỢC PHÉP trả về DUY NHẤT một chuỗi JSON thuần (STRICT JSON), KHÔNG kèm bất kỳ định dạng markdown nào khác ngoài cấu trúc JSON:
{
  "coreSkills": ["NestJS", "TypeScript", "PostgreSQL"],
  "secondarySkills": ["Docker", "Redis", "AWS"],
  "systemScaleScore": 85,
  "githubUrl": "https://github.com/username",
  "portfolioUrl": null,
  "keywordStuffingFlag": false,
  "keywordStuffingReason": null,
  "interviewFocusPoints": ["Hỏi sâu về kinh nghiệm tối ưu truy vấn PostgreSQL", "Kiến trúc microservices"],
  "matchScore": 88,
  "techScore": 90,
  "experienceYears": 4,
  "summary": "Ứng viên có nền tảng vững vàng về Backend...",
  "softSkills": ["Làm việc nhóm Agile", "Giao tiếp kỹ thuật tốt"],
  "recommendation": "FAST_TRACK_INTERVIEW"
}`;

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    cvText,
    promptText
  }
}];

const promptNodeData = $('Build Detailed Gemini Prompt').first().json;
const candidateId = promptNodeData.candidateId;
const candidateName = promptNodeData.candidateName;
const candidateEmail = promptNodeData.candidateEmail;
const jobTitle = promptNodeData.jobTitle;
const cvText = promptNodeData.cvText || '';
const responseJson = $json;

let parsed = null;
const rawText = responseJson.candidates?.[0]?.content?.parts?.[0]?.text;

if (rawText) {
  let cleanedText = rawText.trim();
  if (cleanedText.startsWith('```json')) {
    cleanedText = cleanedText.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleanedText.startsWith('```')) {
    cleanedText = cleanedText.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  try {
    parsed = JSON.parse(cleanedText);
  } catch (e) {
    parsed = null;
  }
}

// Extract GitHub link cleanly
const ghMatch = cvText.match(/(?:https?:\/\/)?(?:www\.)?github\.com\/([a-zA-Z0-9_-]+)\b/i);
const extractedGithubUrl = ghMatch ? (ghMatch[0].startsWith('http') ? ghMatch[0] : 'https://' + ghMatch[0]) : null;

const commonTech = [
  'React', 'NodeJS', 'TypeScript', 'JavaScript', 'NestJS', 'PostgreSQL', 'Docker', 'AWS',
  'Python', 'Git', 'Next.js', 'REST API', 'GraphQL', 'Tailwind', 'HTML/CSS', 'CI/CD',
  'Redis', 'Kubernetes', 'Golang', 'Java', 'Spring Boot', 'Vue', 'Angular', 'Express',
  'MongoDB', 'PHP', 'Laravel', 'MySQL'
];
const matched = commonTech.filter(tech => new RegExp('\\b' + tech.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'i').test(cvText));

// Thuật toán kiểm tra bối cảnh dự án để tránh False Positive cho Senior nhiều kỹ năng:
const projectActionVerbs = ['phát triển', 'thiết kế', 'xây dựng', 'tối ưu', 'dự án', 'kinh nghiệm', 'trách nhiệm', 'vận hành', 'triển khai', 'kiến trúc', 'developed', 'architected', 'optimized', 'project', 'experience'];
const actionVerbMatches = projectActionVerbs.filter(v => cvText.toLowerCase().includes(v));

// Dấu hiệu nhồi từ khóa thực sự: Liệt kê dày đặc từ khóa nhưng không có câu văn mô tả dự án/trách nhiệm
const hasLittleContext = actionVerbMatches.length <= 1 && cvText.length < 800;
const pureBuzzwordDump = (matched.length >= 5 && actionVerbMatches.length === 0 && cvText.length < 500) || (matched.length >= 7 && hasLittleContext);
const extremeDensity = matched.length >= 13 && cvText.length < 1200 && actionVerbMatches.length <= 2;
const isAlgorithmicStuffing = pureBuzzwordDump || extremeDensity;

// Cờ cảnh báo: Tôn trọng cờ của Gemini AI hoặc thuật toán nhận diện buzzword dump
let keywordStuffingFlag = false;
let keywordStuffingReason = null;

if (parsed && typeof parsed.keywordStuffingFlag === 'boolean') {
  keywordStuffingFlag = parsed.keywordStuffingFlag;
  keywordStuffingReason = parsed.keywordStuffingReason || (keywordStuffingFlag ? 'AI phát hiện mật độ từ khóa công nghệ bất thường so với nội dung dự án thực tế' : null);
} else {
  keywordStuffingFlag = isAlgorithmicStuffing;
  keywordStuffingReason = keywordStuffingFlag ? 'Mật độ từ khóa công nghệ quá dày đặc nhưng thiếu mô tả bối cảnh dự án thực tế' : null;
}

if (!parsed || typeof parsed !== 'object') {
  const coreSkills = matched.slice(0, 4);
  const secondarySkills = matched.slice(4);
  const baseScore = keywordStuffingFlag ? 55 : Math.min(65 + coreSkills.length * 6, 92);
  const yearsMatch = cvText.match(/(\d+)\+?\s*(?:năm|years?)/i);
  const expYears = yearsMatch ? parseInt(yearsMatch[1], 10) : (coreSkills.length >= 3 ? 3 : 1);

  parsed = {
    coreSkills: coreSkills.length > 0 ? coreSkills : ['JavaScript', 'HTML/CSS'],
    secondarySkills: secondarySkills,
    systemScaleScore: keywordStuffingFlag ? 35 : (coreSkills.some(s => ['Docker', 'AWS', 'PostgreSQL', 'Kubernetes', 'Redis'].includes(s)) ? 75 : 55),
    githubUrl: extractedGithubUrl,
    portfolioUrl: null,
    keywordStuffingFlag,
    keywordStuffingReason,
    interviewFocusPoints: keywordStuffingFlag
      ? ['Kiểm tra xem ứng viên có thực sự nắm chắc các công nghệ đã liệt kê', 'Yêu cầu ứng viên giải thích chi tiết 1 dự án cụ thể']
      : [
          `Kiểm tra kỹ năng lập trình thực tế với ${coreSkills[0] || 'ngôn ngữ cốt lõi'}`,
          'Thẩm định các dự án thực tế đã trực tiếp triển khai',
          'Đánh giá khả năng tối ưu hiệu năng và xử lý lỗi hệ thống'
        ],
    matchScore: baseScore,
    techScore: baseScore,
    experienceYears: expYears,
    summary: keywordStuffingFlag
      ? `Hồ sơ ứng viên ${candidateName} có dấu hiệu liệt kê dày đặc từ khóa công nghệ (${matched.length} công nghệ) nhưng thiếu mô tả dự án thực tế. Cần phỏng vấn kỹ.`
      : `Hồ sơ ứng viên ${candidateName} có thế mạnh chuyên môn cho vị trí ${jobTitle}. Nắm vững các công nghệ trọng tâm (${coreSkills.join(', ') || 'Công nghệ phần mềm'}).`,
    softSkills: ['Giao tiếp tốt', 'Làm việc nhóm Agile'],
    recommendation: baseScore >= 80 ? 'FAST_TRACK_INTERVIEW' : (baseScore >= 50 ? 'MANUAL_REVIEW' : 'TALENT_POOL_ARCHIVE')
  };
}

// Sanitize & Clamp fields (Cảnh báo nhồi từ khóa KHÔNG loại hồ sơ, giữ trạng thái aiStatus = DONE)
let matchScore = typeof parsed.matchScore === 'number' ? parsed.matchScore : (parseFloat(parsed.matchScore) || 75);
if (matchScore > 100) matchScore = 100;
if (matchScore < 0) matchScore = 0;

let techScore = typeof parsed.techScore === 'number' ? parsed.techScore : (parseFloat(parsed.techScore) || matchScore);
let systemScaleScore = typeof parsed.systemScaleScore === 'number' ? parsed.systemScaleScore : (parseInt(parsed.systemScaleScore, 10) || 60);
if (systemScaleScore > 100) systemScaleScore = 100;
if (systemScaleScore < 0) systemScaleScore = 0;

let experienceYears = typeof parsed.experienceYears === 'number' ? Math.round(parsed.experienceYears) : (parseInt(parsed.experienceYears, 10) || 0);

const coreSkills = Array.isArray(parsed.coreSkills) ? parsed.coreSkills : [];
const secondarySkills = Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : [];
const combinedSkills = coreSkills.length > 0 ? [...coreSkills, ...secondarySkills] : (Array.isArray(parsed.parsedSkillsJson) ? parsed.parsedSkillsJson : []);

let githubUrl = (typeof parsed.githubUrl === 'string' && parsed.githubUrl.trim().length > 0 && parsed.githubUrl.toLowerCase() !== 'null') ? parsed.githubUrl.trim() : extractedGithubUrl;
let portfolioUrl = (typeof parsed.portfolioUrl === 'string' && parsed.portfolioUrl.trim().length > 0 && parsed.portfolioUrl.toLowerCase() !== 'null') ? parsed.portfolioUrl.trim() : null;

const interviewFocusPoints = Array.isArray(parsed.interviewFocusPoints) && parsed.interviewFocusPoints.length > 0 
  ? parsed.interviewFocusPoints 
  : [
      `Kiểm tra kỹ năng lập trình thực chiến với ${coreSkills[0] || 'công nghệ chính'}`,
      'Đánh giá kinh nghiệm xử lý bài toán chịu tải và tối ưu cơ sở dữ liệu'
    ];

const summary = typeof parsed.summary === 'string' && parsed.summary.trim().length > 0
  ? parsed.summary.trim()
  : "Đã hoàn thành đánh giá hồ sơ ứng viên theo tiêu chuẩn Tech ATS.";

const softSkills = Array.isArray(parsed.softSkills) ? parsed.softSkills : ['Làm việc nhóm', 'Giao tiếp tốt'];
let recommendation = parsed.recommendation || (matchScore >= 80 ? 'FAST_TRACK_INTERVIEW' : (matchScore >= 50 ? 'MANUAL_REVIEW' : 'TALENT_POOL_ARCHIVE'));

// Build rich parsedSkillsJson object that is 100% backward compatible for frontend
const parsedSkillsJson = {
  skills: combinedSkills,
  coreSkills,
  secondarySkills,
  systemScaleScore,
  githubUrl,
  portfolioUrl,
  keywordStuffingFlag,
  keywordStuffingReason,
  interviewFocusPoints,
  techScore,
  softSkills,
  recommendation
};

return [{
  json: {
    candidateId,
    name: candidateName,
    email: candidateEmail,
    jobTitle,
    matchScore,
    techScore,
    systemScaleScore,
    experienceYears,
    summary,
    githubUrl,
    portfolioUrl,
    keywordStuffingFlag,
    keywordStuffingReason,
    interviewFocusPoints,
    coreSkills,
    secondarySkills,
    parsedSkillsJson,
    softSkills,
    recommendation
  }
}];

const candidate = $('Parse & Validate AI Evaluation').first().json;
const candidateId = candidate.candidateId;
const candidateName = candidate.name || 'Ứng viên tiềm năng';
const candidateEmail = candidate.email || 'candidate@example.com';
const jobTitle = candidate.jobTitle || 'Vị trí ứng tuyển';
const matchScore = candidate.matchScore;
const techScore = candidate.techScore;
const skills = Array.isArray(candidate.parsedSkillsJson) ? candidate.parsedSkillsJson.join(', ') : '';
const summary = candidate.summary || '';

// Đề xuất ngày phỏng vấn sau 3 ngày làm việc lúc 09:30 AM
const interviewDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000);
interviewDate.setHours(9, 30, 0, 0);
const formattedDate = interviewDate.toLocaleDateString('vi-VN', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});
const formattedTime = '09:30 - 10:30 (Giờ Việt Nam)';

const randomRoomId = Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 5);
const googleMeetUrl = `https://meet.google.com/${randomRoomId}`;

const emailHtml = `
<div style="font-family: 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
  <div style="background: linear-gradient(135deg, #10b981 0%, #059669 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
    <h1 style="margin: 0; font-size: 24px; font-weight: 800;">THƯ MỜI PHỎNG VẤN TRỰC TUYẾN</h1>
    <p style="margin: 8px 0 0 0; font-size: 14px; opacity: 0.9;">AI Recruitment Agent • Fast-Track Interview</p>
  </div>
  <div style="padding: 32px 24px; color: #1e293b;">
    <p style="font-size: 15px; line-height: 1.6;">Kính gửi <strong>${candidateName}</strong>,</p>
    <p style="font-size: 14px; line-height: 1.6; color: #334155;">
      Chúc mừng bạn! Hồ sơ ứng tuyển của bạn cho vị trí <strong>${jobTitle}</strong> đã được hệ thống AI đánh giá rất cao với điểm tương thích ấn tượng <strong style="color: #10b981; font-size: 16px;">${matchScore}%</strong> (Điểm kỹ thuật: ${techScore}%).
    </p>
    <div style="background: #f0fdf4; border: 1px solid #bbf7d0; border-radius: 12px; padding: 20px; margin: 20px 0;">
      <h3 style="margin: 0 0 10px 0; color: #047857; font-size: 14px;">LỊCH HẸN PHỎNG VẤN TRỰC TUYẾN</h3>
      <p style="margin: 4px 0; font-size: 13px;"><strong>Thời gian:</strong> ${formattedTime}, ${formattedDate}</p>
      <p style="margin: 4px 0; font-size: 13px;"><strong>Đường dẫn Google Meet:</strong> <a href="${googleMeetUrl}" style="color: #059669; font-weight: 700;">${googleMeetUrl}</a></p>
    </div>
    <p style="font-size: 13px; color: #64748b;">Trân trọng,<br><strong>Hội đồng Tuyển dụng & AI Recruitment Agent</strong></p>
  </div>
</div>`;

return [{
  json: {
    action: 'FAST_TRACK_INTERVIEW_SCHEDULED',
    tier: 'TIER_1_EXCELLENT',
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    techScore,
    skills,
    summary,
    interviewDate: formattedDate,
    interviewTime: formattedTime,
    googleMeetUrl,
    emailSubject: `[HR Tech] Thư mời phỏng vấn vị trí ${jobTitle} - ${candidateName}`,
    emailHtml
  }
}];

const data = $json;
return [{
  json: {
    success: true,
    alertType: 'HIGH_PRIORITY_CANDIDATE',
    message: `[AI RECRUITMENT] Ứng viên xuất sắc ${data.candidateName} đạt ${data.matchScore}% cho vị trí ${data.jobTitle}. Đã tạo phòng Meet: ${data.googleMeetUrl}`,
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    matchScore: data.matchScore,
    scheduledInterview: `${data.interviewTime}, ${data.interviewDate}`,
    googleMeetUrl: data.googleMeetUrl,
    timestamp: new Date().toISOString()
  }
}];

const candidate = $('Parse & Validate AI Evaluation').first().json;
const candidateId = candidate.candidateId;
const candidateName = candidate.name || 'Ứng viên';
const candidateEmail = candidate.email || 'candidate@example.com';
const jobTitle = candidate.jobTitle || 'Vị trí ứng tuyển';
const matchScore = candidate.matchScore;
const skills = Array.isArray(candidate.parsedSkillsJson) ? candidate.parsedSkillsJson.join(', ') : '';
const summary = candidate.summary || '';

const emailHtml = `
<div style="font-family: 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
  <div style="background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
    <h1 style="margin: 0; font-size: 22px; font-weight: 800;">THÔNG BÁO XÉT DUYỆT HỒ SƠ</h1>
    <p style="margin: 8px 0 0 0; font-size: 14px; opacity: 0.9;">AI Recruitment Agent • HR Review</p>
  </div>
  <div style="padding: 32px 24px; color: #1e293b;">
    <p style="font-size: 15px; line-height: 1.6;">Kính gửi <strong>${candidateName}</strong>,</p>
    <p style="font-size: 14px; line-height: 1.6; color: #334155;">
      Cảm ơn bạn đã ứng tuyển vị trí <strong>${jobTitle}</strong>. Hồ sơ của bạn đã vượt qua vòng sơ loại tự động với điểm tương thích <strong>${matchScore}%</strong>.
    </p>
    <div style="background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 12px; padding: 18px; margin: 20px 0;">
      <p style="margin: 0; font-size: 13px; color: #1e40af; line-height: 1.6;">
        Hồ sơ của bạn hiện đang được chuyển tới Trưởng bộ phận chuyên môn xem xét chi tiết các dự án và kinh nghiệm liên quan. Chúng tôi sẽ thông báo kết quả cụ thể trong vòng 2-3 ngày làm việc.
      </p>
    </div>
    <p style="font-size: 13px; color: #64748b;">Trân trọng,<br><strong>Ban Tuyển dụng & AI Recruitment Agent</strong></p>
  </div>
</div>`;

return [{
  json: {
    action: 'MANUAL_HR_REVIEW_QUEUED',
    tier: 'TIER_2_POTENTIAL',
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    skills,
    summary,
    reviewStatus: 'PENDING_HIRING_MANAGER_REVIEW',
    emailSubject: `[HR Tech] Cập nhật tiến độ hồ sơ ứng tuyển ${jobTitle} - ${candidateName}`,
    emailHtml
  }
}];

const data = $json;
return [{
  json: {
    success: true,
    queueType: 'MANUAL_REVIEW_QUEUE',
    candidateId: data.candidateId,
    candidateName: data.candidateName,
    jobTitle: data.jobTitle,
    matchScore: data.matchScore,
    actionRequired: 'Trưởng bộ phận chuyên môn xem xét CV trong 48h',
    queuedAt: new Date().toISOString()
  }
}];

const candidate = $('Parse & Validate AI Evaluation').first().json;
const candidateId = candidate.candidateId;
const candidateName = candidate.name || 'Ứng viên';
const candidateEmail = candidate.email || 'candidate@example.com';
const jobTitle = candidate.jobTitle || 'Vị trí ứng tuyển';
const matchScore = candidate.matchScore;
const skills = Array.isArray(candidate.parsedSkillsJson) ? candidate.parsedSkillsJson.join(', ') : '';

const emailHtml = `
<div style="font-family: 'Segoe UI', Roboto, sans-serif; max-width: 600px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
  <div style="background: linear-gradient(135deg, #475569 0%, #1e293b 100%); padding: 32px 24px; text-align: center; color: #ffffff;">
    <h1 style="margin: 0; font-size: 22px; font-weight: 800;">THƯ CẢM ƠN ỨNG TUYỂN</h1>
    <p style="margin: 8px 0 0 0; font-size: 13px; opacity: 0.85;">AI Recruitment Agent • Talent Pool Retention</p>
  </div>
  <div style="padding: 32px 24px; color: #1e293b;">
    <p style="font-size: 15px; line-height: 1.6;">Kính gửi <strong>${candidateName}</strong>,</p>
    <p style="font-size: 14px; line-height: 1.6; color: #334155;">
